// Hand-maintained Arabic supplement, merged OVER the generated `AR` dictionary.
//
// `AR` (src/data/generated/ar.ts) is regenerated from the design bundle and must
// not be hand-edited. This file is where translations the generator never
// produced — or produced badly — live. PreferencesProvider builds its lookup as
// `{ ...AR, ...AR_OVERRIDES }`, so an entry here WINS over the generated one,
// letting us both fill gaps and correct a bad generated string.
//
// Keep it aligned with `scripts/check-i18n.mjs`: that gate reports every literal
// translation key with no Arabic, and each one belongs here until it exits clean.
//
// House terms, kept consistent with ar.ts: bay = خليج, receipt = سند قبض,
// post/posting (ledger) = ترحيل, lead = عميل محتمل, requisition = طلب شراء,
// estimate = عرض سعر. Brand names, env vars and units (SALIS AUTO, SAR,
// VITE_API_URL, YYYY-MM, ZATCA, OBD, IFRS, API) are left verbatim.
