  "1 branch · 4–9 bays": "فرع واحد · ٤–٩ خلجان",
  "1 branch · up to 10 users · 10 GB of documents": "فرع واحد · حتى ١٠ مستخدمين · ١٠ جيجابايت من المستندات",
  "1 branch · up to 5 users · 10 GB of documents": "فرع واحد · حتى ٥ مستخدمين · ١٠ غيغابايت من المستندات",
