  "Amount claimed (SAR)": "المبلغ المُطالَب به (SAR)",
  "Amount received": "المبلغ المستلَم",
  "Amounts are stored in halalas and rounded once, at the total. Floating point in a fiscal document is a rounding error waiting for an auditor, and the alternative costs nothing but discipline at the boundary.": "تُخزَّن المبالغ بالهللات وتُقرَّب مرة واحدة عند الإجمالي. الفاصلة العائمة في مستند مالي خطأ تقريب ينتظر مدققًا، والبديل لا يكلّف سوى الانضباط عند الحدود.",
  "An assistant that answers over the workshop’s own data, a repair knowledge base the floor adds to, and scheduling help that reads the bay board. Suggestions, never silent authority: an agent proposes, a role approves.": "مساعد يجيب من بيانات الورشة نفسها، وقاعدة معرفة إصلاح تضيف إليها الأرضية، ومساعدة جدولة تقرأ لوحة الخلجان. اقتراحات، لا سلطة صامتة: الوكيل يقترح، والدور يعتمد.",
  "An estimate raised by you cannot be approved by you. The queue flags one you raised from the server standing, and the server refuses it on submit either way.": "لا يمكنك اعتماد عرض سعر رفعته بنفسك. يشير سجل الانتظار إلى ما رفعته وفقًا لحالة الخادم، ويرفضه الخادم عند الإرسال في كل الأحوال.",
  "An estimate raised by you cannot be approved by you. The server refuses that on submit — this inbox cannot show it in advance, because the estimate does not carry who raised it.": "لا يمكنك اعتماد عرض سعر رفعته بنفسك. يرفض الخادم ذلك عند الإرسال — ولا يمكن لهذا الصندوق إظهاره مسبقًا لأن العرض لا يحمل من رفعه.",
  "An inspection line becomes an estimate line, becomes a parts reservation, becomes an invoice line, becomes a journal entry. Nothing is exported, reconciled or retyped between domains, and every change writes its audit row in the same transaction.": "بند الفحص يصبح بند عرض سعر، ثم حجز قطعة، ثم بند فاتورة، ثم قيداً محاسبياً. لا شيء يُصدَّر أو يُطابَق أو يُعاد إدخاله بين المجالات، وكل تغيير يكتب سطر تدقيقه في المعاملة نفسها.",
  "An unexpected error occurred.": "حدث خطأ غير متوقع.",
