  "Approved and awaiting settlement. Paying releases the approved amount.": "معتمد وبانتظار التسوية. يؤدي الدفع إلى صرف المبلغ المعتمد.",
  "Approved and pending claims": "المطالبات المعتمدة والمعلّقة",
  "Approved by": "اعتمده",
  "Approved inside the role’s ceiling — an advisor to SAR 5,000, a storekeeper to 10,000, a branch manager to 50,000 — and sent to the supplier as a purchase order with a price the catalogue already agreed.": "يُعتمد ضمن سقف الدور — مستشار حتى SAR 5,000، وأمين مستودع حتى 10,000، ومدير فرع حتى 50,000 — ويُرسل إلى المورّد أمر شراء بسعر سبق أن أقرّه الكتالوج.",
  "Approving and receiving need purchase orders on the server. This build is reading design fixtures, which hold none — so there is nothing to approve or receive against here.": "يتطلب الاعتماد والاستلام وجود أوامر شراء على الخادم. تقرأ هذه النسخة بيانات التصميم الثابتة التي لا تحتوي على أي منها — لذا لا يوجد ما يُعتمد أو يُستلم مقابله هنا.",
  "Approving requires a one-time code, a captured e-signature and the linked estimate. None of those endpoints are connected yet, so approval happens on the estimate itself for now.": "يتطلب الاعتماد رمزًا لمرة واحدة وتوقيعًا إلكترونيًا مُلتقطًا وعرض السعر المرتبط. لم تُوصَّل أيٌّ من هذه النقاط بعد، لذا يجري الاعتماد على عرض السعر نفسه في الوقت الحالي.",
  "Approximate distribution across jobs": "التوزيع التقريبي عبر أوامر العمل",
