  "Check-in": "الاستقبال",
  "Check-in progress": "تقدّم تسجيل الوصول",
  "Check-in, inspection, estimate, repair, quality check and delivery — held in order by a server-side state machine that refuses a card trying to skip a stage.": "الاستقبال، والفحص، وعرض السعر، والإصلاح، وضبط الجودة، والتسليم — يحفظ ترتيبها آلة حالات على الخادم ترفض أي بطاقة تحاول تخطي مرحلة.",
  "Check-in, inspection, estimate, repair, quality check, delivery — with two gates that need a different person entirely, which is the moment the system stops being a record and starts being a control.": "الاستقبال، والفحص، وعرض السعر، والإصلاح، وضبط الجودة، والتسليم — ببوابتين تحتاج كل منهما شخصًا مختلفًا تمامًا، وهي اللحظة التي يكف فيها النظام عن كونه سجلًا ويبدأ كونه ضابطًا.",
  "Check-in, inspection, estimate, repair, quality check, delivery. The order is held by a server-side state machine, not by habit: a card that skips a stage is refused, and two of the six are gates — the customer signs the estimate before any work starts, and the technician who did the repair can never be the one who passes its quality check.": "الاستقبال، والفحص، وعرض السعر، والإصلاح، وضبط الجودة، والتسليم. ترتيبها تحفظه آلة حالات على الخادم لا العادة: البطاقة التي تتخطى مرحلة تُرفض، واثنتان من الست بوابتان — يوقّع العميل عرض السعر قبل بدء أي عمل، والفني الذي نفّذ الإصلاح لا يمكن أن يكون من يجيز ضبط جودته.",
  "Checking in...": "جارٍ تسجيل الوصول...",
