  "Customer, technician, supplier, procurement, kiosk and super admin. Six ways in, each with its own permissions, each seeing exactly its own slice and nothing adjacent to it.": "العميل، والفني، والمورّد، والمشتريات، والاستقبال الذاتي، والمشرف العام. ستة مداخل، لكل منها صلاحياته، ويرى كل منها شريحته بالضبط ولا شيء مجاورًا لها.",
  "Customers and fleets": "العملاء والأساطيل",
  "Customers and vehicles, with the Saudi formats validated where they are entered: plate patterns, +966 numbers, national ID. A vehicle keeps its service history across branches and across owners.": "العملاء والمركبات، مع التحقق من الصيغ السعودية عند إدخالها: أنماط اللوحات، وأرقام ‎+966، والهوية الوطنية. وتحتفظ المركبة بسجل صيانتها عبر الفروع وعبر المُلّاك.",
  "Customers are created at check-in or from the portal.": "يُنشأ العملاء عند تسجيل الدخول أو من البوابة.",
  "Customers with 5+ vehicles and monthly service spend above SAR 2,000": "العملاء الذين لديهم ٥+ مركبات وإنفاق خدمة شهري يتجاوز ٢٬٠٠٠ ريال",
