  "Customers, vehicles, job cards, invoices, journals and the audit trail leave in full, whenever you ask, whether or not the last invoice is paid. Exit terms are a design decision, and this one was made early.": "العملاء والمركبات وبطاقات العمل والفواتير واليوميات ومسار التدقيق تخرج كاملة، متى طلبت، سُدِّدت آخر فاتورة أم لا. شروط الخروج قرار تصميمي، وهذا القرار اتُّخذ مبكرًا.",
