  "Estimates are raised after inspection.": "تُرفع عروض الأسعار بعد الفحص.",
  "Estimates awaiting customer sign-off": "التقديرات بانتظار موافقة العميل",
  "Estimates signed same day": "عروض أسعار مُوقَّعة في اليوم نفسه",
  "Estimates, to sign by one-time code": "عروض أسعار، تُوقَّع برمز لمرة واحدة",
  "Evaluation": "التقييم",
  "Every change and every refusal": "كل تغيير وكل رفض",
  "Every change carries a row: who, when, from what, to what. The argument ends by reading rather than by seniority.": "كل تغيير يحمل سطرًا: من، ومتى، ومن أي حالة، وإلى أي حالة. ينتهي الجدال بالقراءة لا بالأقدمية.",
  "Every conversation with a customer, wherever it started, lands in one thread against one vehicle — and the follow-up is scheduled before the call ends rather than remembered afterwards.": "كل محادثة مع عميل، أينما بدأت، تستقر في خيط واحد على مركبة واحدة — وتُجدوَل المتابعة قبل أن تنتهي المكالمة لا أن تُتذكَّر بعدها.",
  "Every feature worth being proud of is downstream of one decision: write who changed what, when, from what, to what — for everything, forever, with no exceptions for convenience. It is also the cheapest support tool ever built, because most arguments end by reading.": "كل ميزة تستحق الفخر هي نتيجة قرار واحد: سجّل من غيّر ماذا، ومتى، ومن أي حالة، وإلى أي حالة — لكل شيء، وإلى الأبد، دون استثناءات لأجل الراحة. وهي كذلك أرخص أداة دعم بُنيت يومًا، لأن معظم الخلافات تنتهي بالقراءة.",
  "Every figure is the amount the server computed for that invoice": "كل رقم هو المبلغ الذي حسبه الخادم لتلك الفاتورة",
  "Every inbound and outbound call with disposition and recording": "كل مكالمة واردة وصادرة مع التصنيف والتسجيل",
  "Every invoice goes through the Phase 2 pipeline: UBL 2.1 XML, a TLV QR code carrying five tags, a SHA-256 hash chained to the invoice before it, an X.509 signature, and the Fatoora API — standard invoices cleared in real time, simplified invoices reported. VAT is computed on the server at the ZATCA rate and never accepted from the browser, and invoices are retained for seven years.": "تمر كل فاتورة بمسار المرحلة الثانية: ملف UBL 2.1 بصيغة XML، ورمز QR بنظام TLV يحمل خمسة وسوم، وبصمة SHA-256 مسلسلة إلى الفاتورة التي تسبقها، وتوقيع X.509، وواجهة فاتورة — الفواتير القياسية تُخلَّص فوريًا، والمبسطة تُبلَّغ. وتُحسب ضريبة القيمة المضافة على الخادم بمعدل ZATCA ولا تُقبل أبدًا من المتصفح، وتُحفظ الفواتير سبع سنوات.",
  "Every invoice is settled or cancelled. There is nothing to receipt.": "كل فاتورة مسوّاة أو ملغاة. لا يوجد ما يُسجَّل له سند قبض.",
  "Every movement recorded against the part you select, with the balance it left behind.": "كل حركة مسجّلة على القطعة المختارة، مع الرصيد المتبقي بعدها.",
  "Every part is above its reorder point.": "كل قطعة أعلى من حد إعادة طلبها.",
  "Every part is at or above its reorder point.": "كل قطعة عند حد إعادة طلبها أو أعلى منه.",
  "Every permission check that says no is recorded as carefully as every change that says yes. A boundary you cannot audit is decoration.": "كل فحص صلاحية ينتهي بالرفض يُسجَّل بالعناية نفسها التي يُسجَّل بها كل تغيير ينتهي بالقبول. الحدّ الذي لا يمكن تدقيقه زينة.",
  "Every receipt the system holds": "كل سند قبض يحتفظ به النظام",
  "Every receipt the system holds — amounts as the server reports them": "كل سند قبض يحتفظ به النظام — المبالغ كما يُبلّغ عنها الخادم",
  "Every report screen, one click away": "كل شاشة تقارير، بنقرة واحدة",
  "Every role in SALIS AUTO, what it may do in each module, which fields it may never see, and the duties that must stay separated. This is the contract between design and implementation.": "كل دور في SALIS AUTO، وما يمكنه فعله في كل وحدة، والحقول التي لا يجوز له رؤيتها، والمهام التي يجب أن تبقى مفصولة. هذا هو العقد بين التصميم والتنفيذ.",
  "Every screen in the product, wired to its live route.": "كل شاشة في المنتج، مربوطة بمسارها الفعلي.",
  "Every statement line has been matched.": "تمت مطابقة جميع بنود كشف الحساب.",
  "Every tracked part, with what it holds and what it is worth.": "كل قطعة متتبَّعة، مع ما تحمله من مخزون وقيمته.",
