  "Fits the hardware": "يتلاءم مع الجهاز",
  "Five steps, every invoice, no exceptions: UBL 2.1 XML, a TLV QR code carrying five tags, a SHA-256 hash chained to the invoice before it, an X.509 signature, and clearance through the Fatoora API — standard invoices cleared in real time, simplified ones reported. VAT is computed on the server at the ZATCA rate and never accepted from the browser. Tilt it.": "خمس خطوات، لكل فاتورة، بلا استثناء: ملف UBL 2.1 بصيغة XML، ورمز QR بنظام TLV يحمل خمسة وسوم، وبصمة SHA-256 مسلسلة إلى الفاتورة التي تسبقها، وتوقيع X.509، والتخليص عبر واجهة فاتورة — الفواتير القياسية تُخلَّص فوريًا، والمبسطة تُبلَّغ. وتُحسب ضريبة القيمة المضافة على الخادم بمعدل ZATCA ولا تُقبل أبدًا من المتصفح. أمِل البطاقة.",
  "Five supplier catalogues feed one central store, which issues parts to nine bays.": "خمسة كتالوجات موردين تغذّي مستودعًا مركزيًا واحدًا، يصرف القطع إلى تسعة خلجان.",
