  "Invoices, payments and receipts, stored as integer halalas and rounded once at the total. Standard invoices clear with ZATCA in real time; simplified invoices are reported. VAT is computed on the server and never accepted from the browser.": "الفواتير والمدفوعات وسندات القبض، مخزّنة كهللات صحيحة ومقرَّبة مرة واحدة عند الإجمالي. الفواتير القياسية تُخلَّص مع ZATCA فوريًا؛ والمبسطة تُبلَّغ. وتُحسب ضريبة القيمة المضافة على الخادم ولا تُقبل أبدًا من المتصفح.",
