  "No, and it never has been. Arabic and English are both first-class, right to left included — the same component set, two themes, two reading directions. Arabic copy is written for Arabic rather than translated into it, and a workshop system sold in Saudi Arabia that charged extra for that would deserve to be laughed at.": "لا، ولم تكن كذلك يومًا. العربية والإنجليزية كلتاهما من الدرجة الأولى، بما في ذلك الاتجاه من اليمين إلى اليسار — المجموعة نفسها من المكوّنات، وسمتان، واتجاها قراءة. والنص العربي يُكتب للعربية لا يُترجَم إليها، ونظام ورش يُباع في السعودية ويتقاضى مقابلًا إضافيًا على ذلك يستحق أن يُضحك عليه.",
  "No. The fourteen roles, the twenty-eight permission modules, the approval ceilings and the six separated duty pairs are identical on every plan. What scales is branches, users and support — never the boundary.": "لا. الأدوار الأربعة عشر، ووحدات الصلاحيات الثماني والعشرون، وسقوف الاعتماد، وأزواج المهام الستة المفصولة، متطابقة في كل باقة. ما يتوسع هو الفروع والمستخدمون والدعم — لا الحدود أبدًا.",
