  "Not everyone who touches a job card should be given the whole application. Each portal carries its own permissions and sees exactly its own slice: a supplier never sees a customer, a technician never sees a margin, a customer sees one vehicle — theirs.": "ليس كل من يلمس بطاقة عمل ينبغي أن يُعطى التطبيق كله. كل بوابة تحمل صلاحياتها وترى شريحتها بالضبط: المورّد لا يرى عميلًا أبدًا، والفني لا يرى هامش ربح أبدًا، والعميل يرى مركبة واحدة — مركبته.",
