  "Nothing has been billed yet.": "لم يُفوتَر شيء بعد.",
  "Nothing has moved this part's stock since it was opened.": "لم تحدث حركة على مخزون هذه القطعة منذ افتتاحها.",
  "Nothing here is a layer stacked on another. The domains share one contract package — the same Zod schemas, permission tables and business rules imported by the server and the browser — so an invoice can post its own journal entry and a part can leave stock costed, with nobody carrying the number between systems by hand. Select a node.": "لا شيء هنا طبقة مكدّسة فوق أخرى. تتشارك المجالات حزمة عقد واحدة — مخططات Zod نفسها، وجداول الصلاحيات، وقواعد العمل، يستوردها الخادم والمتصفح معًا — فتستطيع الفاتورة ترحيل قيدها بنفسها، وتخرج القطعة من المخزون محمَّلة بتكلفتها، دون أن ينقل أحد الرقم بين الأنظمة يدويًا. اختر عقدة.",
  "Nothing here yet": "لا شيء هنا بعد",
  "Nothing in the pipeline yet.": "لا شيء في خط الأنابيب بعد.",
  "Nothing in the workshop yet.": "لا شيء في الورشة بعد.",
  "Nothing in this category": "لا شيء في هذه الفئة",
  "Nothing in this view": "لا شيء في هذا العرض",
  "Nothing is deleted and nothing is held hostage. The export runs whether or not the invoice is paid, and it takes everything — customers, vehicles, job cards, invoices, journals and the audit trail. A system that holds your history back is not a system; it is a hostage arrangement.": "لا شيء يُحذف ولا شيء يُحتجز. يعمل التصدير سواء سُدِّدت الفاتورة أم لا، ويأخذ كل شيء — العملاء والمركبات وبطاقات العمل والفواتير واليوميات ومسار التدقيق. النظام الذي يحتجز تاريخك ليس نظامًا؛ بل ترتيب رهينة.",
  "Nothing matches the current filters.": "لا شيء يطابق المرشحات الحالية.",
  "Nothing moved any part in the selected window.": "لم يُحرّك أي شيء أي قطعة في النافذة المحددة.",
  "Nothing moved any part in the selected window. Choose a longer period, or record a movement from the Inventory screen.": "لم يُحرّك أي شيء أي قطعة في النافذة المحددة. اختر فترة أطول، أو سجّل حركة من شاشة المخزون.",
  "Nothing on the roadmap yet": "لا شيء في خارطة الطريق بعد",
  "Nothing scheduled today": "لا شيء مجدول اليوم",
  "Nothing starts until you say so, and nothing is locked in afterwards — the export takes everything, at any time, whether or not the last invoice is paid.": "لا شيء يبدأ حتى تقول ذلك، ولا شيء يُقفَل عليك بعده — التصدير يأخذ كل شيء، في أي وقت، سُدِّدت آخر فاتورة أم لا.",
  "Nothing to approve": "لا شيء للاعتماد",
  "Nothing to summarise yet": "لا يوجد شيء لتلخيصه بعد",
