  "Offers vary by branch and season, and cannot be combined. Ask at booking, or": "تختلف العروض حسب الفرع والموسم، ولا يمكن الجمع بينها. اسأل عند الحجز، أو",
  "Office supplies": "لوازم مكتبية",
