  "Omar Hassan": "عمر حسن",
  "On": "تشغيل",
  "On Android, back closes an open dialog or drawer first, then navigates, and only leaves the app from a home screen.": "في أندرويد، يغلق زر الرجوع أي نافذة أو لوحة مفتوحة أولًا، ثم ينتقل للخلف، ولا يخرج من التطبيق إلا من شاشة رئيسية.",
  "On Hand": "المتوفر",
  "On Hand / Available": "المتوفر / المتاح",
  "On Hand After": "المتوفر بعد",
  "On Hold": "قيد الانتظار",
