  "On Target": "على المستهدف",
  "On Track": "على المسار",
  "On hand": "المتوفر",
  "On the discounted net": "على الصافي بعد الخصم",
  "On-Time Rate": "معدل التسليم في الوقت",
  "On-hand is the sum of its movements, and the reorder point does the remembering, so the money sitting on the shelf stops being a hedge against being wrong.": "المتوفر هو مجموع حركاته، وحد إعادة الطلب هو من يتذكر، فيكف المال الراكد على الرف عن كونه تحوّطًا ضد الخطأ.",
  "On-hand quantity against reorder level": "الكمية المتوفرة مقابل حد إعادة الطلب",
  "On-site compute nodes and workloads": "عقد الحوسبة المحلية وأحمال العمل",
  "Onboarding": "التهيئة",
  "Onboarding and data migration": "التأهيل وترحيل البيانات",
  "Onboarding and migration": "التأهيل والترحيل",
  "One branch, in parallel": "فرع واحد، بالتوازي",
  "One contract, both sides": "عقد واحد، على الجهتين",
  "One customer, many vehicles, and a monthly invoice that has to reconcile against every job card behind it. Preventive schedules by mileage rather than by memory.": "عميل واحد، ومركبات كثيرة، وفاتورة شهرية يجب أن تطابق كل بطاقة عمل خلفها. وجداول وقائية بالمسافة المقطوعة لا بالذاكرة.",
  "One floor, one owner who is still on it, and a business that lives or dies on turnaround. Reception opens the card, the advisor prices it, the customer signs on their phone.": "أرضية واحدة، ومالك ما زال يقف عليها، وعمل يحيا أو يموت بزمن الإنجاز. الاستقبال يفتح البطاقة، والمستشار يسعّرها، والعميل يوقّع على هاتفه.",
  "One job card": "بطاقة عمل واحدة",
  "One life — the vehicle’s. Bookings, the estimate waiting for a signature, the service history and the invoices, on a phone, in Arabic or English.": "حياة واحدة — حياة المركبة. الحجوزات، وعرض السعر المنتظر توقيعًا، وسجل الصيانة، والفواتير، على الهاتف، بالعربية أو الإنجليزية.",
  "One life — the vehicle’s. Signs the estimate, keeps the invoice": "حياة واحدة — حياة المركبة. يوقّع عرض السعر، ويحتفظ بالفاتورة",
  "One number, four systems": "رقم واحد، أربعة أنظمة",
  "One organisation, many branches, one set of books. Every row carries its organisation and its branch, and PostgreSQL row-level security — not application code — decides who may read it. Stock transfers between branches, a call centre answers for all of them, and a branch manager still sees only their own floor.": "منظمة واحدة، وفروع كثيرة، ومجموعة دفاتر واحدة. كل سطر يحمل منظمته وفرعه، وأمان مستوى الصفوف في PostgreSQL — لا كود التطبيق — هو من يقرر من يجوز له قراءته. المخزون يُحوَّل بين الفروع، ومركز اتصال يجيب عنها جميعًا، ومدير الفرع يبقى لا يرى إلا أرضيته.",
  "One person may not…": "لا يجوز لشخص واحد أن…",
  "One person must never hold both sides of these pairs.": "لا يجوز أن يتولى شخص واحد كلا الجانبين من هذه الأزواج.",
  "One platform carries the whole job — check-in, inspection, a signed estimate, the repair, quality control, delivery and a cleared ZATCA invoice — on a single record that nobody re-types. Thirteen domains, fourteen roles, Arabic and English as equals.": "منصة واحدة تحمل المهمة كاملة — الاستقبال، والفحص، وعرض سعر موقّع، والإصلاح، وضبط الجودة، والتسليم، وفاتورة ZATCA مُخلَّصة — على سجل واحد لا يعيد أحد كتابته. ثلاثة عشر مجالًا، وأربعة عشر دورًا، والعربية والإنجليزية متكافئتان.",
  "One platform runs the workshop from check-in to invoice, in Arabic and English, with ZATCA e-invoicing built in and one audit trail.": "منصة واحدة تدير الورشة من الاستقبال إلى الفاتورة، بالعربية والإنجليزية، مع فوترة إلكترونية متوافقة مع الهيئة وسجل تدقيق واحد.",
  "One platform runs the workshop from check-in to invoice, in Arabic and English, with ZATCA e-invoicing built in. Every change is on the audit trail.": "منصة واحدة تدير الورشة من الاستقبال إلى الفاتورة، بالعربية والإنجليزية، مع فوترة إلكترونية متوافقة مع الهيئة مبنية في الأساس. كل تغيير مسجَّل في سجل التدقيق.",
  "One record of the job": "سجل واحد للعمل",
  "One thread per vehicle, across every branch. Approves nothing": "خيط واحد لكل مركبة، عبر كل فرع. لا يعتمد شيئًا",
