  "Parts are where a workshop quietly loses its margin: the part nobody ordered, the one ordered twice, the one issued to a job and never costed onto it. Here stock is": "قطع الغيار هي حيث تفقد الورشة هامشها بهدوء: القطعة التي لم يطلبها أحد، والتي طُلبت مرتين، والتي صُرفت لمهمة ولم تُحمَّل عليها قط. هنا المخزون هو",
