  "SALIS AUTO": "SALIS AUTO",
  "SALIS AUTO Workshop": "ورشة ساليس أوتو",
  "SALIS AUTO home": "الصفحة الرئيسية لـ SALIS AUTO",
  "SALIS AUTO is Saudi Arabia's leading automotive workshop management platform. We empower garages of all sizes with powerful digital tools to streamline operations, delight customers, and grow revenue.": "SALIS AUTO هي المنصة الرائدة لإدارة ورش السيارات في المملكة العربية السعودية. نمكّن الورش بمختلف أحجامها بأدوات رقمية قوية لتبسيط العمليات وإسعاد العملاء وزيادة الإيرادات.",
  "SALIS AUTO is the all-in-one garage management system built for Saudi workshops — from single bays to franchise networks.": "SALIS AUTO هو نظام إدارة الورش الشامل المصمَّم للورش السعودية — من الخليج الواحد إلى شبكات الامتياز.",
