  "SALIS AUTO · GARAGE OS v1.0 — local shell.": "SALIS AUTO · نظام الورشة الإصدار ١٫٠ — طرفية محلية.",
  "SALIS AUTO — Workshop Management for Saudi Arabia": "SALIS AUTO — إدارة الورش في المملكة العربية السعودية",
  "SALIS AUTO — Workshop Management, Saudi Standard": "SALIS AUTO — إدارة ورش السيارات، معيار سعودي",
  "SALIS AUTO — a multi-tenant garage management platform for the Saudi market:": "SALIS AUTO — منصة إدارة ورش متعددة المستأجرين للسوق السعودي:",
  "SALIS Auto Workshop": "ورشة ساليس أوتو",
