  "SAMPLE VEHICLE. Every finding carries a severity, a photograph and a line on the estimate. The card cannot move to repair until the customer has signed, and every change to it writes an audit row: who, when, from what, to what.": "مركبة نموذجية. كل ملاحظة تحمل درجة خطورة وصورة وبندًا في عرض السعر. ولا يمكن أن تنتقل البطاقة إلى الإصلاح حتى يوقّع العميل، وكل تغيير عليها يكتب سطر تدقيق: من، ومتى، ومن أي حالة، وإلى أي حالة.",
