  "Sample tenant. No tenant data reaches this page.": "مستأجر نموذجي. لا تصل بيانات أي مستأجر إلى هذه الصفحة.",
  "Saudi Arabia first, then the Gulf and the region. Less retyping, less waiting, less guessing: the system drafts, schedules and reconciles, and people decide. Built to lead by removing friction, not by adding features.": "السعودية أولاً، ثم الخليج والمنطقة. إعادة إدخال أقل، وانتظار أقل، وتخمين أقل: النظام يصوغ ويجدول ويطابق، والناس يقررون. بُني ليتصدر بإزالة الاحتكاك لا بإضافة الميزات.",
