  "Six pairs of duties are split and stay split: the technician who did the repair cannot pass its quality check, and nobody approves their own requisition. No deadline has ever been allowed to collapse that.": "ستة أزواج من المهام مفصولة وتبقى مفصولة: الفني الذي نفّذ الإصلاح لا يجيز ضبط جودته، ولا يعتمد أحد طلب الشراء الخاص به. ولم يُسمح لموعد تسليم قط بأن يُسقِط ذلك.",
