  // ── Homepage enterprise-SaaS redesign (2026-09) ──
  "Every plan is configured to your workshop — modules, branches, users and integrations. A specialist scopes it with you before any commitment.": "كل باقة تُهيَّأ حسب ورشتك — الوحدات، والفروع، والمستخدمون، والتكاملات. يحدد أخصائي نطاقها معك قبل أي التزام.",
  "Talk to sales, not a script": "تحدث مع المبيعات، لا مع نص جاهز",
  "Illustrative — the shape of the flow, not a live board": "توضيحي — شكل سير العمل، لا لوحة حية",
  "JOB CARD · SIX STAGES": "بطاقة العمل · ست مراحل",
  "One number, entered once,": "رقم واحد، يُدخل مرة واحدة،",
  "SALIS AUTO runs the workshop from check-in to a ZATCA Phase 2-cleared invoice — one job card, one audit trail, in Arabic and English on the same day. Thirteen domains, fourteen roles, one tenancy.": "ساليس أوتو يدير الورشة من الاستقبال حتى فاتورة معتمدة من مرحلة ZATCA الثانية — بطاقة عمل واحدة، وسجل تدقيق واحد، بالعربية والإنجليزية في اليوم نفسه. ثلاثة عشر مجالًا، وأربعة عشر دورًا، ومستأجر واحد.",
  "SALIS AUTO · Workshop management, Saudi standard": "ساليس أوتو · إدارة الورش، بالمعيار السعودي",
  "See how it works": "شاهد كيف يعمل",
  "The six-stage job card, check-in through delivery": "بطاقة العمل ذات المراحل الست، من الاستقبال حتى التسليم",
  "carried everywhere.": "يُحمل إلى كل مكان.",
  "14 roles, each with a ceiling it cannot cross": "14 دورًا، لكل منها سقف لا يتجاوزه",
  "APPROVAL CEILINGS · SAMPLE DATA": "سقوف الاعتماد · بيانات نموذجية",
  "Approves nothing": "لا يعتمد شيئًا",
  "Diagnostic read & inspection": "قراءة تشخيصية وفحص",
  "Front brake discs & pads": "أقراص وتيل الفرامل الأمامية",
  "Hash 7F2A·C41E·9B03 · verifiable": "البصمة 7F2A·C41E·9B03 · قابلة للتحقق",
  "INVOICE · SAMPLE DATA": "فاتورة · بيانات نموذجية",
  "JOB CARDS · SAMPLE DATA": "بطاقات العمل · بيانات نموذجية",
  "Labour — 2.4 h": "العمالة — 2.4 ساعة",
  "The six-stage job card, held in order by the server": "بطاقة العمل ذات المراحل الست، يحفظ الخادم ترتيبها",
  "UBL 2.1, TLV QR, X.509 — cleared through Fatoora": "UBL 2.1، ورمز QR من نوع TLV، وX.509 — مُخلّصة عبر فاتورة",
  "ZATCA Phase 2": "مرحلة ZATCA الثانية",
  "Architecture principles": "مبادئ البنية",
  "Design note — the problem the platform was built to end": "ملاحظة تصميم — المشكلة التي بُنيت المنصة لإنهائها",
  "“The hard part was never the diagnosis. It was that six people wrote the same number into four systems and one of them was wrong by Thursday.”": "«لم يكن الجزء الصعب هو التشخيص قط. بل أن ستة أشخاص كتبوا الرقم نفسه في أربعة أنظمة، وكان أحدها خاطئًا بحلول الخميس.»",
  "What workshops running it say": "ماذا تقول الورش التي تستخدمه",
  "Job card stages": "مراحل بطاقة العمل",
  "An audit row for every write": "سطر تدقيق لكل عملية كتابة",
  "A shared package holds the Zod schemas, permission tables and business rules — one definition is the API type, the server guard and the form validator at once.": "حزمة مشتركة تحمل مخططات Zod، وجداول الصلاحيات، وقواعد العمل — تعريف واحد يكون نوع واجهة البرمجة، وحارس الخادم، ومدقق النموذج في آن واحد.",
  "PostgreSQL row-level security. Every row carries its organisation and branch, and the database decides who may read it — not a forgotten where clause.": "أمان على مستوى الصف في PostgreSQL. كل صف يحمل مؤسسته وفرعه، وقاعدة البيانات هي من تقرر من يجوز له قراءته — لا شرط WHERE منسي.",
  "UBL 2.1, TLV QR, a SHA-256 hash chain and an X.509 signature, cleared through Fatoora rather than filed after the fact.": "UBL 2.1، ورمز QR من نوع TLV، وسلسلة بصمات SHA-256، وتوقيع X.509، مُخلّصة عبر فاتورة بدلاً من تقديمها لاحقًا.",
  "Who changed what, when, from what, to what — for every write, and for every refusal too. Money moves as integer halalas, rounded once, at the total.": "من غيّر ماذا، ومتى، ومن أي حالة، وإلى أي حالة — لكل عملية كتابة، ولكل رفض أيضًا. والمال يتحرك كهللات صحيحة، ويُقرَّب مرة واحدة عند الإجمالي.",
  "Built on": "مبني على",
  "Structure, not a slide": "بنية، لا شريحة عرض",
  "What holds the platform up — the same facts a technical buyer would ask for, shown rather than asserted.": "ما يُسند المنصة — الحقائق نفسها التي يسأل عنها المشتري التقني، مُظهَرة لا مُدّعاة.",
  "See it running": "شاهده يعمل",
  "What the floor actually looks at": "ما تنظر إليه أرضية الورشة فعليًا",
  "Three screens from the product, shown with sample data — not a live tenant.": "ثلاث شاشات من المنتج، معروضة ببيانات نموذجية — لا مستأجر حي.",
  "Where it stands": "أين وصل",
  "A version number, not a promise": "رقم إصدار، لا وعد",
  "Real releases, in order — including the one still ahead.": "إصدارات حقيقية، بالترتيب — بما في ذلك ما لا يزال قادمًا.",
  "Functional domains, one tenancy": "مجالات وظيفية، مستأجر واحد",
  "Roles and permission modules": "الأدوار ووحدات الصلاحيات",
  "Separation-of-duty pairs, enforced server-side": "أزواج فصل المهام، مُطبَّقة من جانب الخادم",

