  // Live-API wiring gap inherited from main: Dashboard, accounting reports, CustomerAppPayments, InvoiceCreate/Preview, PurchaseAgentPayments and CustomerApproval.
  "Could not load revenue": "تعذّر تحميل الإيراد",
  "Month to date": "منذ بداية الشهر",
  "Loading the balance sheet…": "جارٍ تحميل الميزانية العمومية…",
  "No accounts of this type": "لا حسابات من هذا النوع",
  "Operating, investing and financing activity": "أنشطة التشغيل والاستثمار والتمويل",
  "Loading the ledger…": "جارٍ تحميل دفتر الأستاذ…",
  "Loading the income statement…": "جارٍ تحميل قائمة الدخل…",
  "Loading the trial balance…": "جارٍ تحميل ميزان المراجعة…",
  "Invoices and payments for your services appear here.": "تظهر هنا فواتير خدماتك ومدفوعاتها.",
  "Payment history and balances": "سجل المدفوعات والأرصدة",
  "Saving a card needs a card-vaulting integration this deployment does not have connected. Nothing is stored here today.": "حفظ البطاقة يحتاج تكاملًا لحفظ بيانات البطاقات غير متصل في هذا النشر. لا يُخزَّن شيء هنا حاليًا.",
  "Assigned when issued": "يُخصَّص عند الإصدار",
  "Seller VAT": "الرقم الضريبي للبائع",
  "Amounts owed to suppliers, by purchase order": "المبالغ المستحقة للموردين، حسب أمر الشراء",
  "PO": "أمر الشراء",
  "Supplier payment tracking is not connected": "تتبع مدفوعات الموردين غير متصل",
  "This system has no accounts-payable record for a purchase order — no paid/outstanding status, due date or payment method. The amounts above are real purchase-order totals; whether and when each has been paid is not tracked yet.": "لا يملك هذا النظام سجل حسابات دائنة لأمر الشراء — لا حالة مدفوع/مستحق، ولا تاريخ استحقاق، ولا طريقة دفع. المبالغ أعلاه هي إجماليات أوامر شراء حقيقية؛ أما متى وهل سُدد كل منها فغير متتبَّع بعد.",
  "Total on Open Orders": "الإجمالي على الطلبات المفتوحة",
  "An expired estimate cannot be signed. Ask your advisor for a current one.": "لا يمكن توقيع عرض سعر منتهي الصلاحية. اطلب من مستشارك عرضًا ساريًا.",
  "Approving requires a one-time code and a captured e-signature. That step is not connected in this build.": "يتطلب الاعتماد رمزًا لمرة واحدة وتوقيعًا إلكترونيًا مُلتقطًا. هذه الخطوة غير متصلة في هذا الإصدار.",
  "Approving requires a one-time code, a captured e-signature and the linked estimate. This link carries no estimate to sign.": "يتطلب الاعتماد رمزًا لمرة واحدة، وتوقيعًا إلكترونيًا مُلتقطًا، وعرض السعر المرتبط. لا يحمل هذا الرابط عرض سعر للتوقيع عليه.",
  "Ask your advisor for a current estimate before approving.": "اطلب من مستشارك عرض سعر ساري قبل الاعتماد.",
  "Estimate details are not available here": "تفاصيل عرض السعر غير متاحة هنا",
  "It was valid until": "كان ساريًا حتى",
  "The line items and total for this estimate could not be loaded. The one-time code below still verifies against the record on the server.": "تعذّر تحميل بنود وإجمالي هذا العرض. لا يزال الرمز أدناه لمرة واحدة يتحقق مقابل السجل على الخادم.",
  "The subtotal, VAT and total due are computed by the estimate the server issues — never in the browser. This link has no estimate attached, so no total is shown here.": "المجموع الفرعي وضريبة القيمة المضافة والإجمالي المستحق تُحسب بواسطة عرض السعر الذي يصدره الخادم — لا في المتصفح أبدًا. لا يحمل هذا الرابط عرض سعر مرفقًا، لذا لا يُعرض إجمالي هنا.",
  "This estimate has already been approved.": "تم اعتماد عرض السعر هذا بالفعل.",
